    'seren_reminder_morning_label': 'Morning Peace Moment (07:30)',
    'seren_reminder_morning_sub': 'Optional calm invitation to breathe or listen before starting your day',
    'seren_reminder_evening_label': 'Evening Unwind Moment (21:30)',
    'seren_reminder_evening_sub': 'Optional gentle reminder to decompress and prepare for rest',
    'seren_morning_peace_notif_title': 'Seren • Peaceful Morning Moment',
    'seren_morning_peace_notif_body': 'Take two unhurried minutes for morning birdsong or a gentle breath whenever you feel ready.',
    'seren_evening_unwind_notif_title': 'Seren • Evening Unwind Sanctuary',
    'seren_evening_unwind_notif_body': 'Ready to set down the day? Rain, cozy fireplace, and bedtime stories are waiting quietly.',

